/**
 * Blocklist of dangerous commands that could cause system harm.
 * Shell injection protection: only allow alphanumeric, spaces, and safe symbols.
 */
const DANGEROUS_PATTERNS = [
  /rm\s+-rf\s+\/\s*$/m,           // rm -rf /
  /rm\s+-rf\s+\/\s+\-{1,2}/m,     // rm -rf / --no-preserve-root
  /:\(\)\s*\{.*\}:\s*;/m,          // fork bomb
  />\s*\/dev\/(sda|sdb|sdc|nvme)/m, // direct disk write
  /dd\s+if=\/dev\/zero/m,          // dd zero wipe
  /mkfs\./m,                        // filesystem format
  /mkswap/m,                        // swap creation
  /chmod\s+-R\s+0+\s+\//m,        // chmod root 0
  /chown\s+-R\s+0:0\s+\//m,       // chown root to 0
]

const READ_ONLY_PREFIXES = ['cat ', 'ls ', 'echo ', 'head ', 'tail ', 'pwd ', 'which ', 'type ', 'printf ']

function isDangerous(command: string): boolean {
  return DANGEROUS_PATTERNS.some(pattern => pattern.test(command))
}

function sanitizeCommand(command: string): string {
  // Only allow safe characters: alphanumeric, spaces, and common shell symbols
  // This prevents shell injection via command substitution, pipes, etc.
  const unsafeChars = /[;&|`$(){}[\]<>!#\\~*?]/g
  if (unsafeChars.test(command.replace(/['"]/g, ''))) {
    // Allow quoted strings but reject unquoted unsafe chars
    const stripped = command.replace(/'(?:[^'\\]|\\.)*'/g, '').replace(/"(?:[^"\\]|\\.)*"/g, '')
    if (unsafeChars.test(stripped)) {
      throw new Error(`Shell injection detected: command contains unsafe characters. Use dedicated tools for file operations instead.`)
    }
  }
  return command
}

export const BashTool: Tool<{ command: string; description?: string }, string> = {
  name: 'bash',
  searchHint: 'execute shell commands',
  inputSchema: {
    type: 'object',
    properties: {
      command: { type: 'string', description: 'Shell command to execute' },
      description: { type: 'string', description: 'What this command does' },
    },
    required: ['command'],
  },

  description() {
    return 'Execute a shell command'
  },

  isConcurrencySafe() {
    return false // Shell is stateful — no concurrency
  },

  isReadOnly(input) {
    return READ_ONLY_PREFIXES.some(p => input.command.trim().startsWith(p))
  },

  isEnabled() {
    return true
  },

  async call(args, context) {
    // Safety check: reject dangerous commands
    if (isDangerous(args.command)) {
      return { data: `Error: Command blocked for safety: pattern matches dangerous operation.` }
    }

    // Sanitize: prevent shell injection
    const safeCommand = sanitizeCommand(args.command)

    return new Promise((resolve) => {
      exec(safeCommand, {
        encoding: 'utf-8',
        timeout: 30000,
        cwd: process.cwd(),
        maxBuffer: 10 * 1024 * 1024, // 10MB
      }, (error, stdout, stderr) => {
        if (error) {
          // Return partial output even on error
          const output = stdout || ''
          const errorOutput = stderr || error.message
          if (output) {
            resolve({ data: output + (errorOutput ? `\nSTDERR:\n${errorOutput}` : '') })
          } else {
            resolve({ data: `Error: ${errorOutput}` })
          }
        } else {
          resolve({ data: stdout })
        }
      })
    })
  },
}

