/**
 * DeepAGI AgentEngine
 *
 * 5-phase submitMessage lifecycle.
 * System prompt adapted from Claude Code's verified structure.
 * Pure hybrid: DeepSeek API + Claude-style prompts + agnostic tooling.
 */

import type {
  SDKMessage, SDKUserMessage, SDKAssistantMessage, EngineConfig, ToolDef, Usage, ContentBlock,
} from '../types/index.js'
import { DeepSeekGateway } from '../gateway/deepseek/DeepSeekGateway.js'
import { QueryPipeline } from './QueryPipeline.js'
import { getAllTools } from '../tools/registry.js'
import type { Tool, Tools } from '../tools/registry.js'
import type { ToolUseContext } from '../tools/ToolUseContext.js'
import { storeMemory, createTurnMemory, initMemoryStore } from '../memory/index.js'
import { trackUsage, getUsage } from '../cost/index.js'

export class AgentEngine {
  private config: EngineConfig
  private mutableMessages: SDKMessage[]
  private abortController: AbortController
  private gateway: DeepSeekGateway
  private totalUsage: Usage = { inputTokens: 0, outputTokens: 0 }
  private tools: Tools
  private toolDefs: ToolDef[]
  private sessionId: string
  private memoryEnabled: boolean
  private turnCount = 0

  constructor(config: EngineConfig) {
    this.config = config
    this.mutableMessages = []
    this.abortController = new AbortController()
    this.gateway = new DeepSeekGateway({
      apiKey: config.deepseekApiKey, baseUrl: config.deepseekBaseUrl, model: config.model,
    })
    this.tools = getAllTools()
    this.toolDefs = config.tools.length > 0
      ? config.tools
      : this.tools.map(t => ({ name: t.name, description: t.description(), inputSchema: t.inputSchema }))
    this.sessionId = crypto.randomUUID()
    this.memoryEnabled = initMemoryStore()
  }

  async *submitMessage(prompt: string, options?: { uuid?: string; isMeta?: boolean }): AsyncGenerator<SDKMessage> {
    const startTime = Date.now()
    this.turnCount++
    let lastStopReason: string | null = null

    this.mutableMessages.push({
      type: 'user', message: { role: 'user', content: prompt },
      parent_tool_use_id: null, uuid: options?.uuid ?? crypto.randomUUID(),
      timestamp: new Date().toISOString(),
    })

    const systemPrompt = this.config.systemPrompt ?? this.getDefaultSystemPrompt()
    let finalAssistantText = ''

    while (true) {
      const pipeline = new QueryPipeline({
        gateway: this.gateway, tools: this.toolDefs, systemPrompt,
        maxTurns: this.config.maxTurns, signal: this.abortController.signal,
        model: this.config.model, memoryEnabled: this.memoryEnabled,
      })

      for await (const message of pipeline.run({ messages: this.mutableMessages, turnCount: this.turnCount })) {
        if (message.type === 'assistant') {
          this.mutableMessages.push(message)
          lastStopReason = message.message.stop_reason ?? null
          const textBlocks = (message.message.content ?? []).filter(
            (c): c is ContentBlock & { type: 'text' } => c.type === 'text',
          )
          finalAssistantText += textBlocks.map(t => t.text).join('')
          // Track token usage from assistant response
          if (message.message.usage) {
            trackUsage(
              message.message.usage.inputTokens,
              message.message.usage.outputTokens,
              message.message.usage.cacheReadInputTokens,
              message.message.usage.cacheCreationInputTokens,
            )
            this.totalUsage.inputTokens += message.message.usage.inputTokens
            this.totalUsage.outputTokens += message.message.usage.outputTokens
          }
          yield message
        } else if (message.type === 'stream_event' && message.event.type === 'message_delta' && message.event.usage) {
          // Track per-stream usage
          if (message.event.usage.output_tokens > 0) {
            // output tokens are tracked here, input was from the request
          }
          yield message
        } else yield message
      }

      const lastAssistant = this.findLastAssistant()
      if (!lastAssistant) break
      const toolUses = (lastAssistant.message.content ?? []).filter(
        (c): c is ContentBlock & { type: 'tool_use' } => c.type === 'tool_use',
      )
      if (toolUses.length === 0) break

      this.turnCount++
      const toolResults = await this.executeToolBatch(toolUses, lastAssistant)
      for (const tr of toolResults) this.mutableMessages.push(tr)

      if (this.config.maxTurns && this.turnCount > this.config.maxTurns) {
        const costInfo = getUsage()
        yield { type: 'result', subtype: 'error_max_turns', is_error: true,
          errors: [`Reached maximum turns (${this.config.maxTurns})`],
          duration_ms: Date.now() - startTime, num_turns: this.turnCount,
          stop_reason: lastStopReason, total_cost_usd: costInfo.totalCostUSD, usage: this.totalUsage,
          session_id: crypto.randomUUID(), uuid: crypto.randomUUID() } as SDKMessage
        return
      }
    }

    if (this.memoryEnabled && finalAssistantText.trim()) {
      try { storeMemory(createTurnMemory(this.sessionId, prompt, finalAssistantText)) } catch {}
    }

    const lastMsg = this.findLastAssistant()
    let textResult = ''
    if (lastMsg) {
      const lastContent = lastMsg.message.content?.at(-1)
      if (lastContent?.type === 'text') textResult = lastContent.text
    }
    const costInfo = getUsage()
    yield { type: 'result', subtype: 'success', is_error: false, result: textResult,
      stop_reason: lastStopReason, duration_ms: Date.now() - startTime, num_turns: this.turnCount,
      total_cost_usd: costInfo.totalCostUSD, usage: this.totalUsage,
      session_id: crypto.randomUUID(), uuid: crypto.randomUUID() } as SDKMessage
  }

  private async executeToolBatch(
    toolUses: Array<ContentBlock & { type: 'tool_use' }>,
    _parentMessage: SDKAssistantMessage,
  ): Promise<SDKMessage[]> {
    const results: SDKMessage[] = []
    for (const block of toolUses) {
      const tool = this.tools.find(t => t.name === block.name)
      if (!tool) { results.push(this.makeToolResult(block.id, `Unknown tool: ${block.name}`, true)); continue }

      const context: ToolUseContext = {
        options: { tools: this.tools, mainLoopModel: this.gateway.model, verbose: this.config.verbose ?? false },
        abortController: this.abortController, messages: this.mutableMessages,
        inProgressToolUseIDs: new Set(), setInProgressToolUseIDs: () => {},
      }
      try {
        if (tool.validateInput) {
          const v = await tool.validateInput(block.input, context)
          if (!v.result) { results.push(this.makeToolResult(block.id, v.message, true)); continue }
        }
        const result = await tool.call(block.input, context)
        const content = typeof result.data === 'string' ? result.data : JSON.stringify(result.data, null, 2)
        results.push(this.makeToolResult(block.id, content))
      } catch (error: unknown) {
        results.push(this.makeToolResult(block.id, error instanceof Error ? error.message : String(error), true))
      }
    }
    return results
  }

  private makeToolResult(toolUseId: string, content: string, isError = false): SDKUserMessage {
    return { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: toolUseId, content, is_error: isError }] }, parent_tool_use_id: toolUseId, uuid: crypto.randomUUID() }
  }

  private findLastAssistant(): SDKAssistantMessage | undefined {
    for (let i = this.mutableMessages.length - 1; i >= 0; i--) {
      if (this.mutableMessages[i]!.type === 'assistant') return this.mutableMessages[i] as SDKAssistantMessage
    }
  }

  interrupt(): void { this.abortController.abort() }
  getMessages(): readonly SDKMessage[] { return this.mutableMessages }

  private getDefaultSystemPrompt(): string {
    return `You are DeepAGI, an interactive agent that helps users with software engineering tasks. Use the instructions below and the tools available to you to assist the user.

IMPORTANT: You must NEVER generate or guess URLs for the user unless you are confident that the URLs are for helping the user with programming. You may use URLs provided by the user in their messages or local files.

# System
- All text you output outside of tool use is displayed to the user. You can use Github-flavored markdown for formatting.
- Tools are run in a permission mode. If a tool call is denied, adjust your approach.
- The system will automatically compress prior messages as it approaches context limits.

# Doing tasks
- The user will primarily ask you to perform software engineering tasks: fixing bugs, adding features, refactoring, explaining code, and more.
- You are highly capable. Defer to user judgment about whether a task is too large.
- Do not propose changes to code you haven't read first. If a user asks about or wants you to modify a file, read it first.
- Don't add features, refactor, or make improvements beyond what was asked.
- If an approach fails, diagnose why before switching tactics. Prioritize writing safe, secure, and correct code.
- Avoid creating helpers or abstractions for one-time operations. Three similar lines of code is better than a premature abstraction.

# Using your tools
- To read files use read instead of cat, head, tail, or sed
- To edit files use edit instead of sed or awk
- To create files use write instead of cat with heredoc or echo redirection
- To search for files use glob instead of find or ls
- To search file contents use grep instead of grep or rg
- Prefer dedicated tools over bash for file operations.

# Executing actions with care
- Before deleting or overwriting, check what you're replacing. If what you find contradicts how it was described, surface that instead of proceeding.
- Destructive operations warrant user confirmation: removing files, overwriting uncommitted changes, and other irreversible actions.

# Tone and style
- Do not use emojis unless the user explicitly requests it.
- Your responses should be short and concise.
- When referencing specific functions or pieces of code include pattern file_path:line_number.

# Output efficiency
- Go straight to the point. Try the simplest approach first. Be extra concise.
- Lead with the answer or action, not the reasoning. Skip filler words and unnecessary transitions.`
  }
}

/**
 * DeepSeek LLM Gateway
 *
 * Ported from Open-ClaudeCode's claude.ts.
 * Equivalence rewrite: OpenAI-compatible Chat Completions API.
 *
 * Key rules:
 * - tool role messages MUST immediately follow the assistant with matching tool_calls
 * - Orphaned tool_results (no matching tool_calls in history) are dropped
 * - Assistant content must be null when tool_calls are present
 */

import type {
  SDKMessage,
  SDKAssistantMessage,
  SDKStreamEvent,
  ContentBlock,
  ToolDef,
} from '../../types/index.js'

// ============================================================================
// Types
// ============================================================================

export type DeepSeekConfig = {
  apiKey: string
  baseUrl?: string
  model?: string
}

export type GatewayOptions = {
  messages: SDKMessage[]
  tools: ToolDef[]
  systemPrompt?: string
  signal: AbortSignal
  model?: string
  maxTokens?: number
  temperature?: number
}

type OpenAIMessage = {
  role: 'system' | 'user' | 'assistant' | 'tool'
  content: string | null
  tool_calls?: Array<{
    id: string
    type: 'function'
    function: { name: string; arguments: string }
  }>
  tool_call_id?: string
}

// ============================================================================
// Gateway
// ============================================================================

export class DeepSeekGateway {
  private config: DeepSeekConfig

  constructor(config: DeepSeekConfig) {
    this.config = {
      baseUrl: 'https://api.deepseek.com',
      model: 'deepseek-chat',
      ...config,
    }
    if (!this.config.baseUrl) this.config.baseUrl = 'https://api.deepseek.com'
    if (!this.config.model) this.config.model = 'deepseek-chat'
  }

  get model(): string {
    return this.config.model!
  }

  /**
   * Stream a chat completion from DeepSeek.
   */
  async *stream(
    options: GatewayOptions,
  ): AsyncGenerator<SDKAssistantMessage | SDKStreamEvent> {
    const converted = this.convertMessagesSafe(options.messages, options.systemPrompt)
    const openAITools = this.convertTools(options.tools)
    const sessionId = crypto.randomUUID()

    const body: Record<string, unknown> = {
      model: options.model ?? this.config.model,
      messages: converted.messages,
      stream: true,
      stream_options: { include_usage: true },
    }

    if (openAITools.length > 0) {
      body.tools = openAITools
      body.parallel_tool_calls = false
    }
    if (options.maxTokens) body.max_tokens = options.maxTokens
    if (options.temperature !== undefined) body.temperature = options.temperature

    const response = await fetch(`${this.config.baseUrl}/v1/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${this.config.apiKey}`,
        'Accept': 'text/event-stream',
      },
      body: JSON.stringify(body),
      signal: options.signal,
    })

    if (!response.ok) {
      const errorText = await response.text().catch(() => 'unknown error')
      // Log dropped tool results for debugging
      if (converted.droppedToolIds.length > 0) {
        throw new Error(
          `DeepSeek API error ${response.status}: ${errorText}\n` +
          `Dropped ${converted.droppedToolIds.length} orphaned tool_results (no matching tool_calls in history).`
        )
      }
      throw new Error(`DeepSeek API error ${response.status}: ${errorText}`)
    }

    // Parse SSE stream
    const reader = response.body!.getReader()
    const decoder = new TextDecoder()
    let buffer = ''
    const pendingToolCalls = new Map<number, { id: string; name: string; arguments: string }>()
    let currentText = ''
    let stopReason: string | null = null
    let textBlockStarted = false
    let contentBlocks: ContentBlock[] = []
    let firstToolUseId: string | null = null

    try {
      while (true) {
        const { done, value } = await reader.read()
        if (done) break

        buffer += decoder.decode(value, { stream: true })
        const lines = buffer.split('\n')
        buffer = lines.pop() || ''

        for (const line of lines) {
          const trimmed = line.trim()
          if (!trimmed || trimmed.startsWith(':')) continue

          if (trimmed.startsWith('data: ')) {
            const data = trimmed.slice(6)
            if (data === '[DONE]') continue

            try {
              const chunk = JSON.parse(data) as any

              if (!chunk.choices || chunk.choices.length === 0) {
                if (chunk.usage) {
                  yield {
                    type: 'stream_event',
                    event: {
                      type: 'message_delta',
                      delta: { stop_reason: stopReason ?? undefined },
                      usage: { output_tokens: chunk.usage.completion_tokens },
                    },
                    session_id: sessionId,
                    uuid: crypto.randomUUID(),
                  }
                }
                continue
              }

              const delta = chunk.choices[0]!.delta
              const finishReason = chunk.choices[0]!.finish_reason

              if (finishReason) {
                stopReason = finishReason === 'tool_calls' ? 'tool_use' : finishReason
              }

              if (delta.content) {
                if (!textBlockStarted) {
                  textBlockStarted = true
                  yield {
                    type: 'stream_event',
                    event: {
                      type: 'content_block_start',
                      index: 0,
                      content_block: { type: 'text', text: '' },
                    },
                    session_id: sessionId,
                    uuid: crypto.randomUUID(),
                  }
                }
                currentText += delta.content
                yield {
                  type: 'stream_event',
                  event: {
                    type: 'content_block_delta',
                    index: 0,
                    delta: { type: 'text_delta', text: delta.content },
                  },
                  session_id: sessionId,
                  uuid: crypto.randomUUID(),
                }
              }

              if (delta.tool_calls) {
                for (const tc of delta.tool_calls) {
                  if (tc.id) {
                    pendingToolCalls.set(tc.index, { id: tc.id, name: '', arguments: '' })
                    yield {
                      type: 'stream_event',
                      event: {
                        type: 'content_block_start',
                        index: pendingToolCalls.size,
                        content_block: { type: 'tool_use', id: tc.id, name: '', input: {} },
                      },
                      session_id: sessionId,
                      uuid: crypto.randomUUID(),
                    }
                  }

                  const pending = pendingToolCalls.get(tc.index)
                  if (pending && tc.function) {
                    if (tc.function.name) pending.name += tc.function.name
                    if (tc.function.arguments) {
                      pending.arguments += tc.function.arguments
                      yield {
                        type: 'stream_event',
                        event: {
                          type: 'content_block_delta',
                          index: tc.index,
                          delta: { type: 'input_json_delta', partial_json: tc.function.arguments },
                        },
                        session_id: sessionId,
                        uuid: crypto.randomUUID(),
                      }
                    }
                  }
                }
              }

              if (currentText && (delta.tool_calls || finishReason)) {
                yield {
                  type: 'stream_event',
                  event: { type: 'content_block_stop', index: 0 },
                  session_id: sessionId,
                  uuid: crypto.randomUUID(),
                }
                textBlockStarted = false
              }
            } catch {
              continue
            }
          }
        }
      }

      // Build final content blocks
      if (currentText) {
        contentBlocks.push({ type: 'text', text: currentText })
      }

      for (const [, tc] of pendingToolCalls) {
        if (!firstToolUseId) firstToolUseId = tc.id
        let parsedInput: Record<string, unknown> = {}
        try {
          parsedInput = tc.arguments ? JSON.parse(tc.arguments) : {}
        } catch {
          parsedInput = { _raw: tc.arguments }
        }
        contentBlocks.push({ type: 'tool_use', id: tc.id, name: tc.name, input: parsedInput })
        yield {
          type: 'stream_event',
          event: { type: 'content_block_stop', index: contentBlocks.length },
          session_id: sessionId,
          uuid: crypto.randomUUID(),
        }
      }

      yield {
        type: 'stream_event',
        event: { type: 'message_stop' },
        session_id: sessionId,
        uuid: crypto.randomUUID(),
      }

      yield {
        type: 'assistant',
        message: {
          role: 'assistant',
          content: contentBlocks,
          stop_reason: stopReason,
        },
        parent_tool_use_id: firstToolUseId,
        uuid: crypto.randomUUID(),
        session_id: sessionId,
      }
    } finally {
      reader.releaseLock()
    }
  }

  // ============================================================================
  // Safe Message Conversion — validates tool pairing
  // ============================================================================

  private convertMessagesSafe(
    messages: SDKMessage[],
    systemPrompt?: string,
  ): { messages: OpenAIMessage[]; droppedToolIds: string[] } {
    const result: OpenAIMessage[] = []
    const droppedToolIds: string[] = []

    if (systemPrompt) {
      result.push({ role: 'system', content: systemPrompt })
    }

    // Build set of all tool_call IDs from assistant messages
    const allToolCallIds = new Set<string>()
    for (const msg of messages) {
      if (msg.type === 'assistant') {
        for (const block of msg.message.content ?? []) {
          if (block.type === 'tool_use') {
            allToolCallIds.add(block.id)
          }
        }
      }
    }

    for (const msg of messages) {
      if (msg.type === 'assistant') {
        const textParts: string[] = []
        const toolCalls: OpenAIMessage['tool_calls'] = []

        for (const block of msg.message.content ?? []) {
          switch (block.type) {
            case 'text':
              textParts.push(block.text)
              break
            case 'tool_use':
              toolCalls.push({
                id: block.id,
                type: 'function',
                function: {
                  name: block.name,
                  arguments: JSON.stringify(block.input),
                },
              })
              break
          }
        }

        // OpenAI rule: content must be null when tool_calls are present
        const assistantMsg: OpenAIMessage = {
          role: 'assistant',
          content: toolCalls.length > 0 ? null : (textParts.join('\n') || null),
        }
        if (toolCalls.length > 0) {
          assistantMsg.tool_calls = toolCalls
        }
        result.push(assistantMsg)

      } else if (msg.type === 'user') {
        const contentBlocks = Array.isArray(msg.message.content) ? msg.message.content : []
        const toolResults = contentBlocks.filter(
          (b): b is ContentBlock & { type: 'tool_result' } => b.type === 'tool_result',
        )
        const textBlocks = contentBlocks.filter(
          (b): b is ContentBlock & { type: 'text' } => b.type === 'text',
        )

        if (toolResults.length > 0) {
          for (const tr of toolResults) {
            // DROP orphaned tool_results (no matching tool_call in history)
            if (!allToolCallIds.has(tr.tool_use_id)) {
              droppedToolIds.push(tr.tool_use_id)
              continue
            }
            result.push({
              role: 'tool',
              content: tr.is_error
                ? `Error: ${tr.content}`
                : (typeof tr.content === 'string' ? tr.content : JSON.stringify(tr.content)),
              tool_call_id: tr.tool_use_id,
            })
          }
        } else if (textBlocks.length > 0) {
          result.push({ role: 'user', content: textBlocks.map(t => t.text).join('\n') })
        } else {
          result.push({
            role: 'user',
            content: typeof msg.message.content === 'string'
              ? msg.message.content
              : JSON.stringify(msg.message.content),
          })
        }
      }
    }

    return { messages: result, droppedToolIds }
  }

  private convertMessages(messages: SDKMessage[], systemPrompt?: string): OpenAIMessage[] {
    return this.convertMessagesSafe(messages, systemPrompt).messages
  }

  private convertTools(tools: ToolDef[]): Array<{
    type: 'function'
    function: { name: string; description: string; parameters: ToolDef['inputSchema']; strict?: boolean }
  }> {
    return tools.map((t: ToolDef) => ({
      type: 'function' as const,
      function: {
        name: t.name,
        description: t.description,
        parameters: t.inputSchema,
        strict: t.strict,
      },
    }))
  }
}

import { Tool } from './Tool.js'
import { ToolUseContext } from './ToolUseContext.js'
import { exec } from 'node:child_process'
import { writeFileSync, readFileSync, mkdirSync } from 'node:fs'
import { dirname, resolve } from 'node:path'

/**
 * Blocklist of dangerous commands that could cause system harm.
 * Shell injection protection: only allow alphanumeric, spaces, and safe symbols.
 */
const DANGEROUS_PATTERNS = [
  /rm\s+-rf\s+\/\s*$/m,           // rm -rf /
  /rm\s+-rf\s+\/\s+\-{1,2}/m,     // rm -rf / --no-preserve-root
  /:\(\)\s*\{.*\}:\s*;/m,          // fork bomb
  />\s*\/dev\/(sda|sdb|sdc|nvme)/m, // direct disk write
  /dd\s+if=\/dev\/zero/m,          // dd zero wipe
  /mkfs\./m,                        // filesystem format
  /mkswap/m,                        // swap creation
  /chmod\s+-R\s+0+\s+\//m,        // chmod root 0
  /chown\s+-R\s+0:0\s+\//m,       // chown root to 0
]

const READ_ONLY_PREFIXES = ['cat ', 'ls ', 'echo ', 'head ', 'tail ', 'pwd ', 'which ', 'type ', 'printf ']

function isDangerous(command: string): boolean {
  return DANGEROUS_PATTERNS.some(pattern => pattern.test(command))
}

function sanitizeCommand(command: string): string {
  // Only allow safe characters: alphanumeric, spaces, and common shell symbols
  // This prevents shell injection via command substitution, pipes, etc.
  const unsafeChars = /[;&|`$(){}[\]<>!#\\~*?]/g
  if (unsafeChars.test(command.replace(/['"]/g, ''))) {
    // Allow quoted strings but reject unquoted unsafe chars
    const stripped = command.replace(/'(?:[^'\\]|\\.)*'/g, '').replace(/"(?:[^"\\]|\\.)*"/g, '')
    if (unsafeChars.test(stripped)) {
      throw new Error(`Shell injection detected: command contains unsafe characters. Use dedicated tools for file operations instead.`)
    }
  }
  return command
}

export const BashTool: Tool<{ command: string; description?: string }, string> = {
  name: 'bash',
  searchHint: 'execute shell commands',
  inputSchema: {
    type: 'object',
    properties: {
      command: { type: 'string', description: 'Shell command to execute' },
      description: { type: 'string', description: 'What this command does' },
    },
    required: ['command'],
  },

  description() {
    return 'Execute a shell command'
  },

  isConcurrencySafe() {
    return false // Shell is stateful — no concurrency
  },

  isReadOnly(input) {
    return READ_ONLY_PREFIXES.some(p => input.command.trim().startsWith(p))
  },

  isEnabled() {
    return true
  },

  async call(args, context) {
    // Safety check: reject dangerous commands
    if (isDangerous(args.command)) {
      return { data: `Error: Command blocked for safety: pattern matches dangerous operation.` }
    }

    // Sanitize: prevent shell injection
    const safeCommand = sanitizeCommand(args.command)

    return new Promise((resolve) => {
      exec(safeCommand, {
        encoding: 'utf-8',
        timeout: 30000,
        cwd: process.cwd(),
        maxBuffer: 10 * 1024 * 1024, // 10MB
      }, (error, stdout, stderr) => {
        if (error) {
          // Return partial output even on error
          const output = stdout || ''
          const errorOutput = stderr || error.message
          if (output) {
            resolve({ data: output + (errorOutput ? `\nSTDERR:\n${errorOutput}` : '') })
          } else {
            resolve({ data: `Error: ${errorOutput}` })
          }
        } else {
          resolve({ data: stdout })
        }
      })
    })
  },
}
